## Part 3: The TaskManager — Business Logic Layer

### Core Manager Class

```python
class TaskManager:
    """Manages a collection of tasks with CRUD operations."""

    def __init__(self):
        self._tasks: dict[int, Task] = {}
        self._next_id: int = 1

    def add_task(self, title: str, priority: str = "medium") -> Task:
        task = Task(self._next_id, title, priority)
        self._tasks[task.id] = task
        self._next_id += 1
        return task

    def get_task(self, task_id: int) -> Task:
        try:
            return self._tasks[task_id]
        except KeyError:
            raise KeyError(f"No task with id {task_id}") from None

    def remove_task(self, task_id: int) -> Task:
        task = self.get_task(task_id)  # raises if missing
        del self._tasks[task_id]
        return task

    def complete_task(self, task_id: int) -> Task:
        task = self.get_task(task_id)
        task.mark_completed()
        return task

    def all_tasks(self) -> list[Task]:
        return list(self._tasks.values())

    def pending_tasks(self) -> list[Task]:
        return [t for t in self._tasks.values() if not t.completed]

    def completed_tasks(self) -> list[Task]:
        return [t for t in self._tasks.values() if t.completed]

    def search(self, keyword: str) -> list[Task]:
        keyword_lower = keyword.lower()
        return [
            t for t in self._tasks.values()
            if keyword_lower in t.title.lower()
        ]

    def sorted_by_priority(self) -> list[Task]:
        return sorted(self._tasks.values(), key=lambda t: t.priority_rank())
```

